print('rows',len(rows), 'header',rows[0].keys())
vals=[]
for row in rows:
 for col in ['delta_a','delta_b']:
  b=zlib.decompress(base64.b64decode(row[col])); n=len(b)//4
  x=struct.unpack('<%df'%n,b)
