 for row in rows:
  for c in ('delta_a','delta_b'):
   b=zlib.decompress(base64.b64decode(row[c])); out[(row['id'],c)]=np.frombuffer(b,dtype='<f4').copy()
 return out
A=load('/tmp/kernel1-out/submission.csv'); B=load('/tmp/ioai-final-buffered-validated.csv')
