for typ in ('delta_a','delta_b'):
 ds=[]; rel=[]; same=[]; rms=[]
 for k in A:
  if k[1]!=typ: continue
  x,y=A[k],B[k]; d=x-y
  ds.append(np.sqrt(np.mean(d*d))); rms.append((np.sqrt(np.mean(x*x)),np.sqrt(np.mean(y*y))))
  same.append(np.array_equal(x,y)); rel.append(np.linalg.norm(d)/(np.linalg.norm(y)+1e-20))
